const $=s=>document.querySelector(s), E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z"/><path d="M9 21v-7h6v7"/>',news:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M7 8h6M7 12h10M7 16h10"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',book:'<path d="M4 5a2 2 0 0 1 2-2h14v17H6a2 2 0 0 0-2 2zM4 5v17M6 20h14"/>',file:'<path d="M6 3h9l4 4v14H6zM15 3v5h4M9 12h7M9 16h7"/>',award:'<circle cx="12" cy="8" r="5"/><path d="m9 13-2 9 5-3 5 3-2-9"/>',send:'<path d="m22 2-7 20-4-9-9-4zM22 2 11 13"/>',users:'<circle cx="9" cy="7" r="4"/><path d="M2 21v-2a6 6 0 0 1 12 0v2M16 3a4 4 0 0 1 0 8M17 15a6 6 0 0 1 5 6"/>',shield:'<path d="m12 2 9 4v6c0 5-3.5 8-9 10-5.5-2-9-5-9-10V6zM9 12l2 2 4-4"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19 12h3M2 12h3M12 2v3M12 19v3M19 5l-2 2M5 19l2-2M19 19l-2-2M5 5l2 2"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 8-3 9h18c0-1-3-2-3-9M10 21h4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M19 12H5m7-7-7 7 7 7"/>',chevron:'<path d="m9 18 6-6-6-6"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',logout:'<path d="M10 17l5-5-5-5m5 5H3m9-9h7a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-7"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',check:'<path d="m4 12 5 5L20 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 18v3h16v-3"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M9 7V5a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2v2M3 13h18"/>',activity:'<path d="M2 12h5l3-7 4 14 3-7h5"/>',graduate:'<path d="m2 9 10-5 10 5-10 5zM6 12v5c4 3 8 3 12 0v-5M22 9v8"/>',layers:'<path d="m12 2 9 5-9 5-9-5zM3 12l9 5 9-5M3 17l9 5 9-5"/>'};
const ic=(n)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.file}</svg>`;
let state={me:null,csrf:null,meta:null,previous:'dashboard',route:'dashboard',data:{},menu:false,modal:null,filter:'',calendarView:'all',authTab:'login'};
const has=p=>state.me?.permissions?.includes(p), role=n=>state.me?.roles?.some(r=>r.name===n);
const fmt=d=>d?new Date(d).toLocaleDateString('fr-FR',{day:'numeric',month:'short',year:'numeric'}):'—';
const fmtTime=d=>d?new Date(d).toLocaleString('fr-FR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'—';
const initials=n=>(n||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
function toast(msg,err=false){const el=$('#toast');el.textContent=msg;el.className='show'+(err?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',4200)}
async function api(path,opt={}){const o={method:opt.method||'GET',headers:{...opt.headers},credentials:'same-origin'};if(opt.data!==undefined){o.headers['Content-Type']='application/json';o.body=JSON.stringify(opt.data)}if(opt.body!==undefined)o.body=opt.body;if(o.method!=='GET'&&state.csrf)o.headers['X-CSRF-Token']=state.csrf;let r=await fetch('/api'+path,o),t=await r.json().catch(()=>({error:'Réponse invalide.'}));if(!r.ok){if(r.status===401&&state.me){state.me=null;renderAuth()}throw Error(t.error||'Erreur de connexion.')}return t}
const badge=(s)=>{let labels={active:'Actif',pending:'En attente',suspended:'Suspendu',disabled:'Désactivé',rejected:'Rejeté',draft:'Brouillon',validated:'Validé',published:'Publié',archived:'Archivé',received:'Reçue',processing:'En cours',waiting:'En attente',treated:'Traitée'};let cl=['active','published','treated','validated'].includes(s)?'green':['pending','draft','received','waiting'].includes(s)?'amber':['rejected','suspended','disabled'].includes(s)?'red':'blue';return `<span class="badge ${cl}">${E(labels[s]||s)}</span>`};
function field(label,name,type='text',value='',attrs=''){return `<div class="field"><label for="f-${E(name)}">${E(label)}</label><input id="f-${E(name)}" name="${E(name)}" type="${type}" value="${E(value)}" ${attrs}></div>`}
function select(label,name,options,value='',attrs=''){return `<div class="field"><label for="f-${E(name)}">${E(label)}</label><select id="f-${E(name)}" name="${E(name)}" ${attrs}>${options.map(o=>{let [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${E(v)}" ${String(v)===String(value)?'selected':''}>${E(l)}</option>`}).join('')}</select></div>`}
function textarea(label,name,value='',attrs=''){return `<div class="field"><label for="f-${E(name)}">${E(label)}</label><textarea id="f-${E(name)}" name="${E(name)}" ${attrs}>${E(value)}</textarea></div>`}
function btn(label,action,klass='secondary',id='',extra=''){return `<button type="button" class="btn ${klass}" data-action="${action}" ${id!==''?`data-id="${E(id)}"`:''} ${extra}>${label}</button>`}
function empty(title='Rien à afficher',description='Les informations apparaîtront ici dès qu’elles seront disponibles.'){return `<div class="empty"><div class="empty-icon">${ic('layers')}</div><strong>${E(title)}</strong><p>${E(description)}</p></div>`}
function heading(tag,title,subtitle,action=''){return `<div class="page-heading"><div><span class="eyebrow">${E(tag)}</span><h1>${E(title)}</h1><p>${E(subtitle)}</p></div><div class="heading-actions">${action}</div></div>`}
const nav=[['dashboard','Vue d’ensemble','home','Espace personnel'],['announcements','Annonces','news','Espace académique'],['calendar','Calendrier','calendar'],['courses','Enseignements','book'],['library','Bibliothèque','file'],['results','Résultats','award'],['requests','Mes demandes','send'],['research','Recherche','graduate'],['users','Utilisateurs','users','Administration','users.manage|users.review'],['roles','Rôles & permissions','shield',null,'roles.manage'],['structure','Structure académique','layers',null,'structure.manage'],['audit','Journal d’audit','activity',null,'audit.view'],['settings','Paramètres','settings',null,'settings.manage'],['notifications','Notifications','bell','Compte'],['profile','Mon profil','users']];
function visibleNav(x){return !x[4]||x[4].split('|').some(has)}
function navTitle(r){return nav.find(x=>x[0]===r)?.[1]||'Accueil'}
function shell(){let shown=nav.filter(visibleNav),last='';let items=shown.map(x=>{let group=x[3]&&x[3]!==last?(last=x[3],`<div class="nav-label">${E(x[3])}</div>`):'';return group+`<button class="nav-item ${state.route===x[0]?'active':''}" data-route="${x[0]}">${ic(x[2])}<span>${E(x[1])}</span>${x[0]==='notifications'&&state.data.dashboard?.unread?`<span class="nav-count">${state.data.dashboard.unread}</span>`:''}</button>`}).join('');$('#app').innerHTML=`<div class="shell"><div class="mobile-overlay ${state.menu?'show':''}" data-action="close-menu"></div><aside class="sidebar ${state.menu?'open':''}"><div class="sidebar-top"><div class="brand"><div class="brand-mark">A</div><div>${E(state.meta?.name||'American Corner')}<small>Université de Bouaké</small></div></div></div><div class="sidebar-scroll">${items}</div><div class="sidebar-foot"><div class="mini-user"><div class="avatar">${E(initials(state.me.name))}</div><div><strong>${E(state.me.name)}</strong><small>${E(role('chef')?'Chef de département':state.me.roles.map(r=>r.name.replaceAll('_',' ')).join(' · '))}</small></div></div><button class="nav-item" data-action="logout">${ic('logout')} Déconnexion</button></div></aside><div class="main"><header class="topbar"><div class="topbar-left"><button class="icon-btn menu-btn" data-action="toggle-menu" aria-label="Ouvrir le menu">${ic('menu')}</button><span class="crumb">Département d’anglais <span style="padding:0 8px">/</span> <strong>${E(navTitle(state.route))}</strong></span></div><div class="topbar-right"><small class="text-muted">${E(state.meta?.years.find(y=>y.active)?.label||'')}</small><button class="icon-btn" data-route="notifications" aria-label="Notifications">${ic('bell')}${state.data.dashboard?.unread?'<span class="red-dot"></span>':''}</button><div class="topbar-user"><b>${E(state.me.name)}</b><small>${E(state.me.level||state.me.roles[0]?.name.replaceAll('_',' ')||'Membre')}</small></div><div class="avatar">${E(initials(state.me.name))}</div></div></header><main class="content" id="page"><div class="empty">Chargement…</div></main></div></div><div id="modal-root"></div>`}
async function navigate(r){if(!state.me)return;if(state.route!==r)state.previous=state.route;state.route=r||'dashboard';state.menu=false;location.hash=state.route;shell();try{await load(r);draw()}catch(e){$('#page').innerHTML=heading('Information','Une erreur est survenue',e.message)+btn('Réessayer','retry');toast(e.message,true)}}
async function load(r){let paths={dashboard:['/dashboard','/announcements','/events','/notifications'],announcements:['/announcements'],calendar:['/events'],courses:['/courses'],library:['/documents'],results:['/results','/courses'],requests:['/requests'],research:['/research'],users:['/users','/roles'],roles:['/roles'],structure:['/years','/courses'],audit:['/audit'],notifications:['/notifications'],profile:['/login-events'],settings:[]};let keys={dashboard:['dashboard','announcements','events','notifications'],results:['results','courses'],users:['users','roles'],structure:['years','courses']};let ps=paths[r]||paths.dashboard,ks=keys[r]||ps.map(p=>p.slice(1));await Promise.all(ps.map(async(p,i)=>{state.data[ks[i]]=await api(p)}));}
function draw(){let page={dashboard:dashboardPage,announcements:announcementsPage,calendar:calendarPage,courses:coursesPage,library:libraryPage,results:resultsPage,requests:requestsPage,research:researchPage,users:usersPage,roles:rolesPage,structure:structurePage,audit:auditPage,settings:settingsPage,notifications:notificationsPage,profile:profilePage}[state.route]||dashboardPage;$('#page').innerHTML=(state.route==='dashboard'?'':`<button class="back-btn" data-action="back">${ic('arrow')} Retour</button>`)+page();if(state.modal)renderModal()}
function dashboardPage(){let d=state.data.dashboard||{},ann=(state.data.announcements?.items||[]).filter(x=>x.status==='published').slice(0,4),ev=(state.data.events?.items||[]).filter(x=>x.starts_at>=new Date().toISOString().slice(0,10)).slice(0,4),not=(state.data.notifications?.items||[]).slice(0,3),stats=has('users.manage')?[[d.users,'Utilisateurs','users'],[d.pending,'Comptes à valider','shield'],[d.open_requests,'Demandes en cours','send'],[d.results_pending,'Notes à valider','award']]:[[ann.length,'Annonces récentes','news'],[ev.length,'Événements à venir','calendar'],[d.open_requests,'Mes demandes actives','send'],[d.unread,'Notifications','bell']];let links=[['Annonces','announcements','news'],['Emploi du temps','calendar','calendar'],['Documents','library','file'],['Résultats','results','award'],['Demandes','requests','send']];if(has('users.manage'))links.unshift(['Comptes','users','users']);return `<div class="welcome"><div><span class="eyebrow">Votre espace · ${E(state.meta?.years.find(y=>y.active)?.label||'')}</span><h1>Bonjour, ${E(state.me.name.split(' ')[0])} 👋</h1><p>${has('users.manage')?'Supervisez le département, validez les comptes et suivez les activités en un seul endroit.':'Retrouvez les informations essentielles du département, adaptées à votre profil.'}</p></div>${btn('Voir les annonces '+ic('chevron'),'go-announcements','')}</div><div class="grid stats">${stats.map(([n,l,i])=>`<div class="card stat-card"><div class="stat-icon">${ic(i)}</div><div class="number">${n??'—'}</div><div class="label">${E(l)}</div><div class="corner"></div></div>`).join('')}</div><div class="quick-links">${links.map(([l,r,i])=>`<button class="quick-link" data-route="${r}">${ic(i)}${E(l)}</button>`).join('')}</div><div class="grid two-col"><div class="card"><div class="card-title"><h2>Dernières annonces</h2><a href="#announcements">Tout voir →</a></div>${ann.length?ann.map(a=>`<div class="list-item"><div class="list-icon">${ic('news')}</div><div class="list-body"><strong>${E(a.title)}</strong><p>${E(a.body.slice(0,110))}${a.body.length>110?'…':''}</p><span class="list-meta">${E(a.category)} · ${fmt(a.created_at)}</span></div></div>`).join(''):empty('Aucune annonce publiée')}</div><div class="grid" style="align-content:start"><div class="card"><div class="card-title"><h2>À venir</h2><a href="#calendar">Calendrier →</a></div>${ev.length?ev.map(e=>`<div class="list-item"><div class="date-chip"><b>${E(new Date(e.starts_at).getDate())}</b><small>${E(new Date(e.starts_at).toLocaleDateString('fr-FR',{month:'short'}))}</small></div><div class="list-body"><strong>${E(e.title)}</strong><span class="list-meta">${E(e.place||e.kind)} · ${fmtTime(e.starts_at)}</span></div></div>`).join(''):empty('Aucun événement programmé')}</div>${has('users.manage')&&d.by_level?.length?`<div class="card"><div class="card-title"><h2>Effectifs par niveau</h2><a href="#users">Utilisateurs →</a></div>${d.by_level.map(x=>`<div class="list-item"><div class="list-body"><strong>${E(x.level)}</strong></div><b>${x.count}</b></div>`).join('')}</div>`:`<div class="card"><div class="card-title"><h2>Notifications</h2><a href="#notifications">Tout voir →</a></div>${not.length?not.map(n=>`<div class="list-item"><div class="list-icon">${ic('bell')}</div><div class="list-body"><strong>${E(n.title)}</strong><span class="list-meta">${fmt(n.created_at)}</span></div></div>`).join(''):empty('Vous êtes à jour')}</div>`}</div></div>`}
const categories=['Annonce officielle','Information pédagogique','Information administrative','Résultats','Emploi du temps','Examen','Soutenance','Conférence','Séminaire','Offre de stage','Offre d’emploi','Bourse','Appel à communication','Urgence','Information générale'];
const audiences=[['all','Tous les membres'],['students','Étudiants'],['teachers','Enseignants'],['licence','Licence'],['master','Master'],['doctorat','Doctorat'],['level','Niveau précis'],['track','Parcours précis'],['role','Rôle précis']];
function announcementsPage(){let all=state.data.announcements?.items||[],v=all.filter(x=>!state.filter||(`${x.title} ${x.body} ${x.category}`).toLowerCase().includes(state.filter.toLowerCase()));return heading('Communication','Annonces du département','Les informations officielles et pédagogiques qui vous concernent.',has('announcements.create')?btn(ic('plus')+' Nouvelle annonce','new-announcement','teal'):'')+`<div class="filters"><input class="search-input" id="filter" placeholder="Rechercher une annonce…" value="${E(state.filter)}"><span class="text-muted">${v.length} publication(s)</span></div><div style="max-width:880px">${v.length?v.map(a=>`<article class="announcement"><div class="announcement-top"><div class="actions">${badge(a.status)}<span class="badge blue">${E(a.category)}</span></div><small>${fmt(a.created_at)}</small></div><h3>${E(a.title)}</h3><p>${E(a.body)}</p><div class="announcement-foot"><span>Par ${E(a.author_name)}</span><span>Public : ${E(a.audience==='all'?'Tous':a.target||a.audience)}</span>${has('announcements.publish')&&a.status==='pending'?btn('Publier','publish-announcement','teal small',a.id):''}${has('announcements.publish')&&a.status==='published'?btn('Archiver','archive-announcement','secondary small',a.id):''}</div></article>`).join(''):empty('Aucune annonce','Les publications validées et pertinentes pour votre profil apparaîtront ici.')}</div>`}
function calendarPage(){let all=state.data.events?.items||[],v=all.filter(x=>state.calendarView==='all'||new Date(x.starts_at)>new Date()&&new Date(x.starts_at)<new Date(Date.now()+(state.calendarView==='week'?7:31)*864e5));return heading('Agenda','Calendrier académique','Cours, examens, séminaires et rendez-vous du département.',has('events.manage')?btn(ic('plus')+' Nouvel événement','new-event','teal'):'')+`<div class="filters"><div class="actions">${[['all','Tous'],['week','7 jours'],['month','30 jours']].map(([id,l])=>`<button class="btn ${state.calendarView===id?'':'secondary'} small" data-action="calendar-filter" data-id="${id}">${l}</button>`).join('')}</div><small>${v.length} événement(s)</small></div><div class="grid two-col"><div class="card"><div class="card-title"><h2>Programme</h2></div>${v.length?v.map(e=>`<div class="list-item"><div class="date-chip"><b>${E(new Date(e.starts_at).getDate())}</b><small>${E(new Date(e.starts_at).toLocaleDateString('fr-FR',{month:'short'}))}</small></div><div class="list-body"><strong>${E(e.title)}</strong><p>${E(e.description)}</p><span class="list-meta">${fmtTime(e.starts_at)} · ${E(e.place||'Lieu à préciser')} · ${E(e.kind)}</span></div></div>`).join(''):empty('Aucun événement sur cette période')}</div><div class="card"><div class="card-title"><h2>Votre calendrier</h2></div><p class="text-muted">Les événements sont filtrés selon votre rôle, votre niveau et votre parcours.</p><div class="muted-note">Les changements importants sont signalés dans vos notifications personnelles.</div><div class="accent-line"><b>Année universitaire en cours</b><br><span class="text-muted">${E(state.meta?.years.find(y=>y.active)?.label||'Non définie')}</span></div></div></div>`}
function coursesPage(){let a=state.data.courses?.items||[];return heading('Pédagogie','Enseignements','Cours organisés par niveau, semestre et année académique.',has('courses.manage')?btn(ic('plus')+' Ajouter un cours','new-course','teal'):'')+`<div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Cours</th><th>Niveau</th><th>Semestre</th><th>Enseignant</th><th>Année</th>${has('results.enter')||has('courses.manage')?'<th>Effectif</th>':''}</tr></thead><tbody>${a.map(x=>`<tr><td><strong>${E(x.title)}</strong><small>${E(x.code)}</small></td><td>${E(x.level)}<small>${E(x.track)}</small></td><td>S${x.semester}</td><td>${E(x.teacher_name||'À attribuer')}</td><td>${E(x.year_label)}</td>${has('results.enter')||has('courses.manage')?`<td>${btn('Voir les étudiants','view-roster','secondary small',x.id)}</td>`:''}</tr>`).join('')}</tbody></table>${!a.length?empty('Aucun cours disponible'):''}</div></div>`}
function libraryPage(){let a=(state.data.documents?.items||[]).filter(x=>!state.filter||`${x.title} ${x.author} ${x.category}`.toLowerCase().includes(state.filter.toLowerCase()));return heading('Ressources','Bibliothèque numérique','Documents et supports accessibles selon vos autorisations.',has('documents.manage')||has('documents.create')?btn(ic('plus')+' Déposer un document','new-document','teal'):'')+`<div class="filters"><input class="search-input" id="filter" placeholder="Titre, auteur ou domaine…" value="${E(state.filter)}"><small>${a.length} document(s)</small></div><div class="grid three-col">${a.map(x=>`<div class="card"><div class="stat-icon">${ic('file')}</div><span class="badge blue">${E(x.category)}</span><h3 style="margin:14px 0 6px">${E(x.title)}</h3><p class="text-muted" style="font-size:12px">${E(x.author||'Département d’anglais')} ${x.document_year?'· '+E(x.document_year):''}</p><div class="actions"><a class="btn small secondary" href="/api/documents/${x.id}/file">${ic('download')} Télécharger</a><small>${(x.size/1024).toFixed(0)} Ko</small></div></div>`).join('')}</div>${!a.length?empty('Aucun document trouvé','Essayez une autre recherche ou revenez plus tard.'):''}`}
function resultsPage(){let a=state.data.results?.items||[];let can=has('results.enter')||has('results.validate');return heading('Évaluations',can?'Gestion des résultats':'Mes résultats',can?'Les notes provisoires ne sont pas visibles par les étudiants.':'Seuls vos résultats officiellement publiés sont affichés.',has('results.enter')?btn(ic('plus')+' Saisir une note','new-result','teal'):'')+`${can?'<div class="muted-note">Circuit officiel : saisie → validation → publication. Toute correction après publication est tracée et requiert un motif.</div>':''}<div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Cours</th>${can?'<th>Étudiant</th>':''}<th>Semestre</th><th>Note / 20</th><th>Statut</th>${has('results.validate')?'<th>Action</th>':''}</tr></thead><tbody>${a.map(x=>`<tr><td><strong>${E(x.course_title)}</strong><small>${E(x.code)} · ${E(x.year_label)}</small></td>${can?`<td>${E(x.student_name)}<small>${E(x.student_identifier)}</small></td>`:''}<td>S${x.semester}</td><td><strong>${Number(x.score).toFixed(2)}</strong></td><td>${badge(x.status)}</td>${has('results.validate')?`<td class="actions-cell">${x.status==='draft'?btn('Valider','validate-result','teal small',x.id):x.status==='validated'?btn('Publier','publish-result','teal small',x.id):btn('Corriger','correct-result','secondary small',x.id)}</td>`:''}</tr>`).join('')}</tbody></table>${!a.length?empty('Aucun résultat disponible',can?'Les notes saisies apparaîtront ici.':'Aucun résultat officiel n’a encore été publié pour votre compte.'):''}</div></div>${!can?`<p style="margin-top:15px">Une erreur constatée ? ${btn('Signaler une erreur de résultat','new-request','secondary small','','data-kind="Vérification de résultats"')}</p>`:''}`}
const requestLabels={received:'Reçue',processing:'En cours de traitement',waiting:'En attente d’informations',treated:'Traitée',rejected:'Rejetée'};
function requestsPage(){let a=state.data.requests?.items||[];return heading('Guichet numérique',has('requests.manage')?'Suivi des demandes':'Mes demandes administratives','Déposez une demande et suivez son traitement en toute confidentialité.',btn(ic('plus')+' Nouvelle demande','new-request','teal'))+`<div class="grid" style="max-width:970px">${a.length?a.map(x=>`<div class="card"><div class="card-title"><div><span class="eyebrow" style="margin-bottom:6px">${E(x.tracking)} · ${E(x.kind)}</span><h3>${E(x.subject)}</h3></div>${badge(x.status)}</div><p class="text-muted">${E(x.body)}</p><div class="announcement-foot">${has('requests.manage')?`<span>Demandeur : ${E(x.owner_name)}</span>`:''}<span>Déposée le ${fmt(x.created_at)}</span>${has('requests.manage')?btn('Traiter','update-request','secondary small',x.id):''}</div>${x.history?.length?`<details style="margin-top:15px"><summary style="cursor:pointer;color:var(--teal);font-weight:700;font-size:12px">Historique (${x.history.length})</summary><div style="margin-top:10px">${x.history.map(h=>`<div class="list-item"><div class="list-body"><strong>${E(requestLabels[h.status]||h.status)}</strong><p>${E(h.note)}</p><small>${E(h.actor_name)} · ${fmtTime(h.created_at)}</small></div></div>`).join('')}</div></details>`:''}</div>`).join(''):empty('Aucune demande pour le moment','Utilisez le bouton « Nouvelle demande » pour contacter le département.')}</div>`}
function researchPage(){let a=state.data.research?.items||[];let student=state.me.level?.startsWith('Master')||state.me.level==='Doctorat';let steps=['Choix du sujet','Validation','Recherche bibliographique','Collecte des données','Rédaction','Corrections','Soutenance'];return heading('Recherche scientifique','Mémoires & thèses','Suivez vos sujets et les étapes de votre travail de recherche.',student?btn(ic('plus')+' Proposer un sujet','new-research','teal'):'')+`${a.length?`<div class="grid two-col">${a.map(x=>`<div class="card"><span class="badge blue">${E(x.kind)}</span><h2 style="margin:16px 0 5px">${E(x.title)}</h2><small>${E(x.owner_name)} · Encadreur : ${E(x.supervisor_name||'Non attribué')}</small><div class="section-gap"><b>${E(x.status)}</b><p class="text-muted" style="font-size:12px">${E(x.notes||'Aucune note de suivi.')}</p></div><div style="border-top:1px solid var(--line);padding-top:10px">${steps.map((s,i)=>`<div class="research-step ${steps.indexOf(x.milestone)>=i?'done':''}"><span class="step-number">${steps.indexOf(x.milestone)>i?'✓':i+1}</span>${E(s)}</div>`).join('')}</div>${(x.owner_id===state.me.id||has('research.manage')||x.supervisor_id===state.me.id)?`<div class="form-actions">${btn('Mettre à jour','edit-research','secondary small',x.id)}</div>`:''}</div>`).join('')}</div>`:empty('Aucun projet de recherche','Les sujets de mémoire et de thèse suivis par le département apparaîtront ici.')}`}
function usersPage(){let a=state.data.users?.items||[];return heading('Administration','Gestion des utilisateurs','Validation, suspension et attribution des rôles avec traçabilité.',has('users.manage')?btn(ic('plus')+' Ajouter un compte','new-user','teal'):'')+`<div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Utilisateur</th><th>Identifiant</th><th>Rôle(s)</th><th>Niveau</th><th>Statut</th><th>Actions</th></tr></thead><tbody>${a.map(x=>`<tr><td><strong>${E(x.name)}</strong><small>${E(x.email)}</small></td><td>${E(x.identifier)}</td><td>${x.roles.map(r=>`<span class="badge blue">${E(r.name.replaceAll('_',' '))}</span>`).join(' ')}</td><td>${E(x.level||'—')}</td><td>${badge(x.status)}</td><td class="actions-cell"><div class="actions">${has('users.manage')?btn('Gérer','edit-user','secondary small',x.id):x.status==='pending'?btn('Valider','approve-user','teal small',x.id):''}</div></td></tr>`).join('')}</tbody></table>${!a.length?empty('Aucun utilisateur'):''}</div></div>`}
function rolesPage(){let a=state.data.roles?.items||[];return heading('Contrôle d’accès','Rôles & permissions','Les permissions sont appliquées sur le serveur, pas seulement dans l’interface.',btn(ic('plus')+' Nouveau rôle','new-role','teal'))+`<div class="grid three-col">${a.map(r=>{let p=JSON.parse(r.permissions);return `<div class="card"><div class="stat-icon">${ic('shield')}</div><h3>${E(r.name.replaceAll('_',' '))}</h3><p class="text-muted" style="font-size:12px">${p.length} permission(s)</p><div style="min-height:70px">${p.slice(0,4).map(x=>`<span class="badge blue" style="margin:3px">${E(x)}</span>`).join('')}${p.length>4?`<small>+${p.length-4} autres</small>`:''}</div><div class="form-actions">${r.name!=='chef'?btn('Configurer','edit-role','secondary small',r.id):'<small>Rôle protégé</small>'}</div></div>`}).join('')}</div>`}
function structurePage(){let years=state.data.years?.items||[],courses=state.data.courses?.items||[];return heading('Organisation','Structure académique','Années, niveaux, parcours et enseignements du département.')+`<div class="grid two-col"><div class="card"><div class="card-title"><h2>Années académiques</h2>${btn(ic('plus')+' Ajouter','new-year','secondary small')}</div>${years.map(x=>`<div class="list-item"><div class="list-body"><strong>${E(x.label)}</strong><small>${x.archived?'Archivée':'Données conservées'}</small></div>${x.active?badge('active'):btn('Activer','activate-year','secondary small',x.id)}</div>`).join('')}</div><div class="card"><div class="card-title"><h2>Niveaux</h2>${btn(ic('plus')+' Ajouter','new-level','secondary small')}</div>${(state.meta?.levels||[]).map(x=>`<div class="list-item"><div class="list-body"><strong>${E(x.name)}</strong><small>${E(x.cycle)}</small></div></div>`).join('')}</div><div class="card"><div class="card-title"><h2>Parcours</h2>${btn(ic('plus')+' Ajouter','new-track','secondary small')}</div>${(state.meta?.tracks||[]).map(x=>`<div class="list-item"><div class="list-body"><strong>${E(x.name)}</strong></div></div>`).join('')}</div><div class="card"><div class="card-title"><h2>Enseignements</h2><a href="#courses">Voir les cours →</a></div><div class="number" style="font:32px Georgia,serif">${courses.length}</div><p class="text-muted">Cours enregistrés, classés par année et semestre.</p></div></div>`}
function auditPage(){let a=state.data.audit?.items||[];return heading('Sécurité','Journal d’audit','Historique en lecture seule des opérations sensibles.')+`<div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Date et heure</th><th>Auteur</th><th>Action</th><th>Objet</th><th>Détails</th></tr></thead><tbody>${a.map(x=>`<tr><td>${fmtTime(x.created_at)}</td><td>${E(x.actor_name||'Système')}</td><td><strong>${E(x.action)}</strong></td><td>${E(x.entity)} #${x.entity_id||'—'}</td><td><small>${E(x.details).slice(0,130)}</small></td></tr>`).join('')}</tbody></table>${!a.length?empty('Aucune opération enregistrée'):''}</div></div>`}
function settingsPage(){return heading('Configuration','Paramètres généraux','Informations de la plateforme et sauvegardes de la base de données.')+`<div class="grid two-col"><div class="card"><div class="card-title"><h2>Identité de l’application</h2></div><form data-form="settings">${field('Nom affiché','platform_name','text',state.meta.name,'required maxlength="90"')}<div class="form-actions"><button class="btn teal" type="submit">Enregistrer</button></div></form></div><div class="card"><div class="card-title"><h2>Sauvegarde</h2></div><p class="text-muted">Créez une copie cohérente de la base SQLite. Le fichier est conservé sur le serveur dans le répertoire de données sécurisé.</p>${btn('Créer une sauvegarde','backup','secondary')}</div></div>`}
function notificationsPage(){let a=state.data.notifications?.items||[];return heading('Votre compte','Notifications','Messages et mises à jour qui vous concernent.',a.some(x=>!x.read_at)?btn('Tout marquer comme lu','read-notifications','secondary'):'')+`<div class="card" style="max-width:850px">${a.length?a.map(n=>`<div class="list-item ${n.read_at?'':'notif-unread'}"><div class="list-icon">${ic('bell')}</div><div class="list-body"><strong>${E(n.title)}</strong><p>${E(n.body)}</p><small>${fmtTime(n.created_at)}</small></div>${n.link?`<button class="btn text" data-route="${E(n.link)}">Voir →</button>`:''}</div>`).join(''):empty('Vous êtes à jour','Aucune nouvelle notification.')}</div>`}
function profilePage(){let u=state.me;return heading('Compte personnel','Mon profil','Modifiez vos coordonnées et protégez votre accès.')+`<div class="grid two-col"><div class="card"><div class="card-title"><h2>Informations personnelles</h2></div><form data-form="profile">${field('Nom et prénoms','name','text',u.name,'required')}${field('Adresse e-mail','email','email',u.email,'disabled')}${field('Téléphone','phone','tel',u.phone||'')}${field('Identifiant','identifier','text',u.identifier,'disabled')}<div class="form-actions"><button class="btn teal" type="submit">Enregistrer</button></div></form></div><div class="card"><div class="card-title"><h2>Sécurité du compte</h2></div><form data-form="password-change">${field('Mot de passe actuel','current','password','','required')}${field('Nouveau mot de passe','password','password','','required minlength="10"')}<p class="field-hint">Au moins 10 caractères, avec lettres et chiffres.</p><div class="form-actions"><button class="btn secondary" type="submit">Changer le mot de passe</button></div></form><div class="muted-note section-gap">Rôle(s) : ${u.roles.map(r=>E(r.name.replaceAll('_',' '))).join(', ')}. Les changements de rôle sont effectués uniquement par le département.</div><h3>Connexions récentes</h3>${(state.data['login-events']?.items||[]).slice(0,6).map(x=>`<div class="list-item"><div class="list-body"><strong>${x.success?'Connexion réussie':'Tentative refusée'}</strong><small>${fmtTime(x.created_at)} · ${E(x.ip)}</small></div></div>`).join('')||'<small>Aucune connexion enregistrée.</small>'}</div></div>`}
function authFields(){let tab=state.authTab,meta=state.meta||{years:[],levels:[],tracks:[]};if(tab==='login')return `<form data-form="login">${field('Adresse e-mail','email','email','','required autocomplete="username"')}${field('Mot de passe','password','password','','required autocomplete="current-password"')}<div style="text-align:right;margin:-6px 0 18px"><button class="btn text" type="button" data-action="auth-forgot">Mot de passe oublié ?</button></div><button class="btn teal" style="width:100%;padding:13px" type="submit">Se connecter ${ic('chevron')}</button></form>`;
if(tab==='register')return `<form data-form="register"><div class="form-grid">${field('Nom et prénoms','name','text','','required')}${field('Adresse e-mail','email','email','','required')}${field('Matricule / identifiant','identifier','text','','required')}${field('Téléphone (facultatif)','phone','tel')}${select('Statut','kind',[['etudiant','Étudiant'],['enseignant','Enseignant'],['ancien','Ancien étudiant']], 'etudiant')}<div id="student-extra" style="display:contents">${select('Niveau','level',meta.levels.map(x=>x.name))}${select('Parcours','track',[['','Non précisé'],...meta.tracks.map(x=>x.name)])}${select('Année académique','year_id',meta.years.map(x=>[x.id,x.label]),meta.years.find(x=>x.active)?.id)}</div><div class="full">${field('Mot de passe (10 caractères minimum)','password','password','','required minlength="10"')}</div></div><button class="btn teal" style="width:100%;padding:13px" type="submit">Soumettre ma demande ${ic('chevron')}</button><p class="field-hint" style="text-align:center">Le compte sera activé après vérification par le département.</p></form>`;
if(tab==='forgot')return `<form data-form="forgot">${field('Adresse e-mail du compte','email','email','','required')}<button class="btn teal" style="width:100%" type="submit">Envoyer les instructions</button><button class="btn text" type="button" data-action="auth-login">← Retour à la connexion</button></form>`;
return `<form data-form="reset">${field('Nouveau mot de passe','password','password','','required minlength="10"')}<button class="btn teal" style="width:100%" type="submit">Réinitialiser le mot de passe</button></form>`}
function renderAuth(){let t=state.authTab;if(location.hash.startsWith('#reset/'))t=state.authTab='reset';$('#app').innerHTML=`<div class="auth"><section class="auth-story"><div class="brand"><div class="brand-mark">A</div><div>${E(state.meta?.name||'American Corner')}<small>Département d’anglais</small></div></div><div class="auth-heading"><span class="eyebrow">Université de Bouaké · Côte d’Ivoire</span><h1>Un espace pour <em>apprendre, partager et avancer.</em></h1><p>Toute la vie académique du département réunie dans un espace simple et sécurisé.</p></div><div class="story-bottom"><i></i><span>Votre département. Vos ressources. Votre avenir.</span></div></section><div class="auth-side"><div class="auth-card"><span class="eyebrow">Accès à la plateforme</span><h2>${E({login:'Bienvenue',register:'Rejoindre le département',forgot:'Mot de passe oublié',reset:'Nouveau mot de passe'}[t])}</h2><p>${E({login:'Connectez-vous à votre espace personnel.',register:'Créez votre compte et attendez sa validation.',forgot:'Nous vous aiderons à retrouver votre accès.',reset:'Choisissez un nouveau mot de passe sécurisé.'}[t])}</p>${['login','register'].includes(t)?`<div class="auth-switch"><button class="${t==='login'?'active':''}" data-action="auth-login">Connexion</button><button class="${t==='register'?'active':''}" data-action="auth-register">Inscription</button></div>`:''}${authFields()}${state.meta?.demo?`<div class="demo-box"><strong>Mode démonstration</strong><br>Chef : <code>admin@american-corner.test</code> / <code>DemoAdmin2026!</code><br>Étudiant : <code>etudiant@american-corner.test</code> / <code>DemoUser2026!</code><br>Enseignant : <code>enseignant@american-corner.test</code> / <code>DemoUser2026!</code></div>`:''}</div></div></div>`}
function modal(title,html){state.modal={title,html};renderModal()}
function renderModal(){if(!state.modal)return;let root=$('#modal-root');if(!root)return;root.innerHTML=`<div class="modal-backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-label="${E(state.modal.title)}"><div class="modal-head"><h2>${E(state.modal.title)}</h2><button type="button" data-action="close-modal" aria-label="Fermer">×</button></div>${state.modal.html}</div></div>`;root.querySelector('input,select,textarea')?.focus()}
function closeModal(){state.modal=null;let root=$('#modal-root');if(root)root.innerHTML=''}
function formModal(type,id='',hint=''){let meta=state.meta,u=state.me,years=meta.years.map(x=>[x.id,x.label]),levels=meta.levels.map(x=>x.name),tracks=[['','Tous les parcours'],...meta.tracks.map(x=>x.name)];let defaultAudience=(has('announcements.publish')||role('secretariat')||has('documents.manage'))?'all':role('responsable_parcours')?'track':role('enseignant')?'teachers':role('ancien')?'students':'level';let defaultTarget=defaultAudience==='track'?u.track:defaultAudience==='level'?u.level:'';let audienceFields=select('Public concerné','audience',audiences,defaultAudience)+field('Cible si niveau, parcours ou rôle','target','text',defaultTarget||'','placeholder="Ex. Licence 2"');let html='',title='';
if(type==='announcement'){title='Nouvelle annonce';html=`<form data-form="announcement">${field('Titre','title','text','','required maxlength="180"')}${select('Catégorie','category',categories,'Information pédagogique')}${textarea('Contenu','body','','required')}${audienceFields}${select('Année académique','year_id',[['','Non spécifiée'],...years],years.find(x=>x[0]===meta.years.find(y=>y.active)?.id)?.[0]||'')}<div class="muted-note">${has('announcements.publish')?'Vous pouvez publier directement ou soumettre pour validation.':'L’annonce sera soumise au circuit de validation avant sa diffusion.'}</div><div class="form-actions">${has('announcements.publish')?'<button class="btn secondary" type="submit" name="mode" value="pending">Soumettre</button>':''}<button class="btn teal" type="submit" name="mode" value="publish">${has('announcements.publish')?'Publier':'Soumettre'}</button></div></form>`}
if(type==='event'){title='Nouvel événement';html=`<form data-form="event">${field('Titre','title','text','','required')}${select('Type','kind',['Cours','Examen','Séminaire','Soutenance','Conférence','Réunion','Événement'])}<div class="form-grid">${field('Début','starts_at','datetime-local','','required')}${field('Fin (facultatif)','ends_at','datetime-local')}${field('Lieu','place')}</div>${textarea('Description','description')}${audienceFields}<div class="form-actions"><button class="btn teal">Ajouter au calendrier</button></div></form>`}
if(type==='course'){title='Ajouter un cours';html=`<form data-form="course">${field('Intitulé du cours','title','text','','required')}${field('Code du cours','code','text','','required')}<div class="form-grid">${select('Niveau','level',levels)}${select('Parcours','track',tracks)}${select('Semestre','semester',[[1,'Semestre 1'],[2,'Semestre 2']])}${select('Année académique','year_id',years,meta.years.find(y=>y.active)?.id)}${select('Enseignant','teacher_id',[['','À attribuer'],...(state.data.users?.items||[]).filter(x=>x.roles.some(r=>r.name==='enseignant')).map(x=>[x.id,x.name])])}</div><div class="form-actions"><button class="btn teal">Enregistrer le cours</button></div></form>`}
if(type==='document'){title='Déposer un document';html=`<form data-form="document">${field('Titre du document','title','text','','required')}${select('Catégorie','category',['Support de cours','Article scientifique','Mémoire','Thèse','Dictionnaire','Linguistique','Littérature','Didactique','Traduction','Méthodologie','Autre'])}<div class="form-grid">${field('Auteur','author')}${field('Année du document','document_year')}${select('Public','audience',audiences,defaultAudience)}${field('Cible si besoin','target','text',defaultTarget||'')}</div>${field('Fichier (PDF, image, texte, DOCX, XLSX — 10 Mo max)','file','file','','required accept=".pdf,.png,.jpg,.jpeg,.txt,.docx,.xlsx"')}<div class="form-actions"><button class="btn teal">Téléverser</button></div></form>`}
if(type==='result'){title='Saisir une note';let courseList=(state.data.courses?.items||[]).filter(x=>has('results.validate')||x.teacher_id===u.id);html=`<form data-form="result">${select('Cours','course_id',courseList.map(x=>[x.id,`${x.title} · ${x.level} · ${x.year_label}`]))}<div id="roster-field">${select('Étudiant','student_id',[[ '', 'Chargement des étudiants…' ]])}</div>${field('Note sur 20','score','number','','required min="0" max="20" step="0.01"')}<div class="muted-note">La note sera enregistrée comme brouillon et restera invisible pour l’étudiant jusqu’à validation et publication.</div><div class="form-actions"><button class="btn teal">Enregistrer la note</button></div></form>`}
if(type==='request'){title='Nouvelle demande';html=`<form data-form="request">${select('Type de demande','kind',['Demande d’information','Attestation','Relevé de notes','Vérification de résultats','Rendez-vous','Mémoire ou thèse','Réclamation administrative','Correction du profil'],hint||'Demande d’information')}${field('Objet','subject','text','','required')}${textarea('Description de votre demande','body','','required')}<div class="form-actions"><button class="btn teal">Envoyer la demande</button></div></form>`}
if(type==='research'){title='Proposer un sujet';html=`<form data-form="research">${field('Sujet de recherche','title','text','','required maxlength="250"')}<div class="muted-note">Votre sujet sera enregistré comme « Sujet proposé ». Il devra être validé par une personne habilitée.</div><div class="form-actions"><button class="btn teal">Proposer le sujet</button></div></form>`}
if(type==='user'){title=id?'Gérer un utilisateur':'Ajouter un compte';if(id){let x=state.data.users.items.find(z=>z.id==id);html=`<form data-form="user-edit" data-id="${id}">${field('Nom et prénoms','name','text',x.name,'required')}${field('Adresse e-mail','email','email',x.email,'disabled')}<div class="form-grid">${select('Statut','status',[['pending','En attente'],['active','Actif'],['suspended','Suspendu'],['disabled','Désactivé'],['rejected','Rejeté']],x.status)}${select('Niveau','level',[['','Aucun'],...levels],x.level)}${select('Parcours','track',tracks,x.track)}</div><div class="field"><label>Rôles attribués</label><div class="role-checks">${state.data.roles.items.map(r=>`<label><input type="checkbox" name="roles" value="${E(r.name)}" ${x.roles.some(z=>z.name===r.name)?'checked':''}>${E(r.name.replaceAll('_',' '))}</label>`).join('')}</div></div>${textarea('Motif (obligatoire en cas de suspension, rejet ou désactivation)','reason')}<div class="form-actions"><button class="btn teal">Enregistrer les modifications</button></div></form>`}else html=`<form data-form="user-create">${field('Nom et prénoms','name','text','','required')}${field('Adresse e-mail','email','email','','required')}${field('Identifiant professionnel ou matricule','identifier','text','','required')}${field('Mot de passe provisoire (10 caractères min.)','password','password','','required minlength="10"')}${select('Rôle','role',state.data.roles.items.map(r=>r.name))}<div class="form-grid">${select('Niveau','level',[['','Aucun'],...levels])}${select('Parcours','track',tracks)}${select('Année académique','year_id',[['','Aucune'],...years],meta.years.find(y=>y.active)?.id)}</div><div class="form-actions"><button class="btn teal">Créer le compte</button></div></form>`}
if(type==='role'){let x=id?state.data.roles.items.find(r=>r.id==id):null;title=x?'Configurer un rôle':'Créer un rôle';let selected=x?JSON.parse(x.permissions):[];html=`<form data-form="role" data-id="${id}">${x?`<div class="muted-note">${E(x.name)} — les utilisateurs concernés devront se reconnecter après modification.</div>`:field('Nom technique du rôle (minuscules et underscores)','name','text','','required pattern="[a-z_]+"')}<div class="field"><label>Permissions</label><div class="role-checks">${state.data.roles.available_permissions.map(p=>`<label><input type="checkbox" name="permissions" value="${E(p)}" ${selected.includes(p)?'checked':''}>${E(p)}</label>`).join('')}</div></div><div class="form-actions"><button class="btn teal">Enregistrer</button></div></form>`}
if(type==='year'){title='Nouvelle année académique';html=`<form data-form="year">${field('Année (ex. 2027–2028)','label','text','','required')}<div class="form-actions"><button class="btn teal">Ajouter</button></div></form>`}
if(type==='level'){title='Ajouter un niveau';html=`<form data-form="level">${field('Nom du niveau','name','text','','required')}${select('Cycle','cycle',['Licence','Master','Doctorat'])}${field('Ordre d’affichage','sort','number',meta.levels.length)}<div class="form-actions"><button class="btn teal">Ajouter</button></div></form>`}
if(type==='track'){title='Ajouter un parcours';html=`<form data-form="track">${field('Nom du parcours','name','text','','required')}<div class="form-actions"><button class="btn teal">Ajouter</button></div></form>`}
if(type==='request-edit'){let x=state.data.requests.items.find(r=>r.id==id);title='Traiter '+x.tracking;html=`<form data-form="request-edit" data-id="${id}">${select('Statut','status',[['received','Reçue'],['processing','En cours'],['waiting','En attente d’informations'],['treated','Traitée'],['rejected','Rejetée']],x.status)}${textarea('Réponse / justification','note',x.response)}<div class="form-actions"><button class="btn teal">Mettre à jour</button></div></form>`}
if(type==='research-edit'){let x=state.data.research.items.find(r=>r.id==id);title='Suivi de recherche';let manager=has('research.manage')||x.supervisor_id===u.id;html=`<form data-form="research-edit" data-id="${id}"><div class="muted-note">${E(x.title)}</div>${manager?select('Statut','status',['Sujet proposé','En attente de validation','Sujet validé','En cours de recherche','En cours de rédaction','En correction','Prêt pour soutenance','Soutenu','Archivé'],x.status)+select('Étape','milestone',['Choix du sujet','Validation','Recherche bibliographique','Collecte des données','Rédaction','Corrections','Soutenance'],x.milestone):''}${has('research.manage')?field('Identifiant de l’encadreur','supervisor_id','number',x.supervisor_id||''):''}${textarea('Notes et commentaires','notes',x.notes)}<div class="form-actions"><button class="btn teal">Enregistrer</button></div></form>`}
if(type==='result-correct'){title='Correction contrôlée';html=`<form data-form="result-correct" data-id="${id}">${field('Nouvelle note sur 20','score','number',state.data.results.items.find(x=>x.id==id)?.score,'required min="0" max="20" step="0.01"')}${textarea('Motif obligatoire de la correction','reason','','required')}<div class="muted-note">La note repassera en brouillon ; elle devra être à nouveau validée puis publiée. La note précédente reste dans le journal d’audit.</div><div class="form-actions"><button class="btn danger">Corriger et tracer</button></div></form>`}
modal(title,html)}
async function refresh(){state.modal=null;await navigate(state.route);state.meta=await api('/meta');}
async function action(name,id,el){try{
 if(name==='close-modal'){if(el?.closest('.modal')&&el.classList.contains('modal-backdrop'))return;closeModal();return}
 if(name==='toggle-menu'){state.menu=!state.menu;shell();draw();return}if(name==='close-menu'){state.menu=false;shell();draw();return}
 if(name.startsWith('auth-')){state.authTab=name.slice(5);renderAuth();return}
 if(name==='retry')return navigate(state.route);
 if(name==='back')return navigate(state.previous||'dashboard');
 if(name==='logout'){await api('/logout',{method:'POST'});state.me=null;state.csrf=null;state.authTab='login';location.hash='';renderAuth();return}
 if(name==='go-announcements')return navigate('announcements');
 if(name==='calendar-filter'){state.calendarView=id;draw();return}
 if(name.startsWith('new-')){let type=name.slice(4);if(type==='course'&&!state.data.users){state.data.users=await api('/users')}formModal(type,'',el?.dataset.kind||'');if(type==='result')loadRoster();return}
 if(name==='edit-user')return formModal('user',id);
 if(name==='view-roster'){let result=await api('/courses/'+id+'/students');let course=state.data.courses.items.find(x=>x.id==id);return modal('Étudiants · '+course.title,result.items.length?`<div class="muted-note">${result.items.length} étudiant(s) inscrits dans le niveau et l’année du cours.</div>${result.items.map(x=>`<div class="list-item"><div class="list-body"><strong>${E(x.name)}</strong><small>${E(x.identifier)} · ${E(x.level)}</small></div></div>`).join('')}`:empty('Aucun étudiant inscrit'))}
 if(name==='edit-role')return formModal('role',id);
 if(name==='update-request')return formModal('request-edit',id);
 if(name==='edit-research')return formModal('research-edit',id);
 if(name==='correct-result')return formModal('result-correct',id);
 if(name==='approve-user'){if(!confirm('Valider ce compte ?'))return;await api('/users/'+id,{method:'PATCH',data:{status:'active'}});toast('Compte validé.');return refresh()}
 if(name==='publish-announcement'||name==='archive-announcement'){let verb=name.startsWith('publish')?'published':'archived';if(!confirm(verb==='published'?'Publier cette annonce pour son public cible ?':'Archiver cette annonce ?'))return;await api('/announcements/'+id,{method:'PATCH',data:{status:verb}});toast('Annonce mise à jour.');return refresh()}
 if(name==='validate-result'||name==='publish-result'){let status=name.startsWith('validate')?'validated':'published';if(!confirm(status==='published'?'Publier ce résultat officiel à l’étudiant ?':'Valider cette note ?'))return;await api('/results/'+id,{method:'PATCH',data:{status}});toast('Résultat mis à jour.');return refresh()}
 if(name==='activate-year'){if(!confirm('Activer cette année académique ? Les données précédentes resteront conservées.'))return;await api('/years/'+id,{method:'PATCH',data:{active:true}});state.meta=await api('/meta');toast('Année académique activée.');return refresh()}
 if(name==='read-notifications'){await api('/notifications/read',{method:'POST'});toast('Notifications marquées comme lues.');return refresh()}
 if(name==='backup'){let d=await api('/backups',{method:'POST'});toast('Sauvegarde créée : '+d.file);return}
 }catch(e){toast(e.message,true)}}
async function submit(form,e){let kind=form.dataset.form,d=Object.fromEntries(new FormData(form).entries()),go=true;let submitter=e.submitter;try{let out;
 if(kind==='login'){out=await api('/login',{method:'POST',data:d});state.me=out.user;state.csrf=out.csrf;state.authTab='login';toast('Bienvenue sur American Corner.');return navigate('dashboard')}
 if(kind==='register'){out=await api('/register',{method:'POST',data:d});toast(out.message);state.authTab='login';return renderAuth()}
 if(kind==='forgot'){out=await api('/password/forgot',{method:'POST',data:d});toast(out.message);if(out.demo_reset_link){let box=document.createElement('div');box.className='demo-box';box.innerHTML=`Lien de réinitialisation (démo) : <a style="text-decoration:underline" href="${E(out.demo_reset_link)}">Ouvrir le lien</a>`;form.after(box)}return}
 if(kind==='reset'){out=await api('/password/reset',{method:'POST',data:{password:d.password,token:location.hash.split('/')[1]}});toast(out.message);location.hash='';state.authTab='login';return renderAuth()}
 if(kind==='profile'){out=await api('/profile',{method:'PATCH',data:d});state.me=out.user;toast('Profil mis à jour.');return refresh()}
 if(kind==='password-change'){await api('/password/change',{method:'POST',data:d});toast('Mot de passe changé. Les autres sessions ont été fermées.');form.reset();return}
 if(kind==='announcement'){d.publish=submitter?.value==='publish';await api('/announcements',{method:'POST',data:d});toast(d.publish&&has('announcements.publish')?'Annonce publiée.':'Annonce soumise pour validation.')}
 if(kind==='event'){await api('/events',{method:'POST',data:d});toast('Événement créé.')}
 if(kind==='course'){d.teacher_id=d.teacher_id||null;await api('/courses',{method:'POST',data:d});toast('Cours enregistré.')}
 if(kind==='document'){let f=form.querySelector('input[type=file]').files[0];if(!f)throw Error('Choisissez un fichier.');let params=new URLSearchParams({...d,filename:f.name});params.delete('file');await api('/documents/upload?'+params,{method:'POST',headers:{'Content-Type':f.type||'application/octet-stream'},body:f});toast('Document conservé sur le serveur.')}
 if(kind==='result'){await api('/results',{method:'POST',data:d});toast('Note enregistrée comme brouillon.')}
 if(kind==='request'){out=await api('/requests',{method:'POST',data:d});toast('Demande enregistrée : '+out.tracking)}
 if(kind==='research'){await api('/research',{method:'POST',data:d});toast('Sujet proposé.')}
 if(kind==='user-create'){await api('/users',{method:'POST',data:d});toast('Compte créé.')}
 if(kind==='user-edit'){d.roles=[...form.querySelectorAll('input[name=roles]:checked')].map(x=>x.value);if(!confirm('Confirmer la modification du compte et de ses accès ?'))return;await api('/users/'+form.dataset.id,{method:'PATCH',data:d});toast('Compte modifié et action auditée.')}
 if(kind==='role'){d.permissions=[...form.querySelectorAll('input[name=permissions]:checked')].map(x=>x.value);await api('/roles'+(form.dataset.id?'/'+form.dataset.id:''),{method:form.dataset.id?'PATCH':'POST',data:d});toast('Rôle enregistré.')}
 if(kind==='year'){await api('/years',{method:'POST',data:d});state.meta=await api('/meta');toast('Année créée.')}
 if(kind==='level'){await api('/levels',{method:'POST',data:d});state.meta=await api('/meta');toast('Niveau créé.')}
 if(kind==='track'){await api('/tracks',{method:'POST',data:d});state.meta=await api('/meta');toast('Parcours créé.')}
 if(kind==='request-edit'){await api('/requests/'+form.dataset.id,{method:'PATCH',data:d});toast('Demande mise à jour.')}
 if(kind==='research-edit'){await api('/research/'+form.dataset.id,{method:'PATCH',data:d});toast('Suivi mis à jour.')}
 if(kind==='result-correct'){if(!confirm('Confirmer cette correction ? L’ancienne note restera dans l’audit.'))return;await api('/results/'+form.dataset.id,{method:'PATCH',data:d});toast('Correction enregistrée. Revalidation nécessaire.')}
 if(kind==='settings'){await api('/settings',{method:'PATCH',data:d});state.meta=await api('/meta');toast('Paramètres enregistrés.')}
 if(go){closeModal();await refresh()}
 }catch(err){toast(err.message,true)}}
document.addEventListener('click',async e=>{let route=e.target.closest('[data-route]');if(route){e.preventDefault();return navigate(route.dataset.route)}let a=e.target.closest('[data-action]');if(a){if(a.classList.contains('modal-backdrop')&&e.target!==a)return;e.preventDefault();return action(a.dataset.action,a.dataset.id||'',a)}});
document.addEventListener('submit',e=>{let f=e.target.closest('form[data-form]');if(f){e.preventDefault();let button=e.submitter;if(button){button.disabled=true;setTimeout(()=>button.disabled=false,1300)}submit(f,e)}});
async function loadRoster(){let selectCourse=$('#modal-root select[name=course_id]'),field=$('#roster-field');if(!field||!selectCourse)return;let id=selectCourse.value;if(!id){field.innerHTML='<div class="muted-note">Aucun cours attribué. Contactez le département.</div>';return}try{let d=await api('/courses/'+id+'/students');field.innerHTML=select('Étudiant','student_id',d.items.length?d.items.map(x=>[x.id,x.name+' · '+x.identifier]):[['','Aucun étudiant inscrit']]);}catch(e){field.innerHTML=`<div class="muted-note">${E(e.message)}</div>`}}
document.addEventListener('change',e=>{if(e.target.matches('select[name=course_id]'))loadRoster();if(e.target.matches('select[name=kind]')){let extra=$('#student-extra');if(extra)extra.style.display=e.target.value==='etudiant'?'contents':'none'}});
document.addEventListener('input',e=>{if(e.target.id==='filter'){state.filter=e.target.value;let pos=e.target.selectionStart;draw();let input=$('#filter');input?.focus();input?.setSelectionRange(pos,pos)}});
window.addEventListener('hashchange',()=>{if(!state.me){if(location.hash.startsWith('#reset/')){state.authTab='reset';renderAuth()}return}let r=location.hash.slice(1).split('/')[0];if(r!==state.route&&nav.some(x=>x[0]===r))navigate(r)});
(async()=>{try{state.meta=await api('/meta');let m=await api('/me');state.me=m.user;state.csrf=m.csrf;if(state.me){let r=location.hash.slice(1);await navigate(nav.some(x=>x[0]===r&&visibleNav(x))?r:'dashboard')}else renderAuth()}catch(e){$('#app').innerHTML=`<div class="empty"><strong>Connexion au serveur impossible</strong><p>${E(e.message)}</p></div>`}})();
